def register(add):
    add("T112", title="内存分配与逃逸分析", level="advanced", kind="module-project", runtime="desktop",
        files=["go.mod", "main.go"], codeFile="main.go", vkind="stdout-exact",
        expected="value: 1 2\npointer: 3 4\ninterface: {5 6}\nhint: `go build -gcflags=-m .` shows which variables escape to the heap", run="go run .",
        concepts=["逃逸分析", "堆/栈", "gcflags -m", "性能"],
        summary="用 -gcflags=-m 查看逃逸报告，理解返回值、返回指针、存入接口的不同分配行为。",
        objective="能用 gcflags=-m 判断变量是否逃逸，并据此减少堆分配。",
        prereq=["T030 指针二：指针与切片/映射的关系", "T041 接口基础与鸭子类型"],
        pitfalls=["以为返回结构体一定拷贝很贵：小结构体按值返回通常栈分配、可被内联优化。", "盲目用指针避免“拷贝”：可能导致逃逸到堆，反而增加 GC 压力。"],
        exercises=[{"prompt": "对 makeValue/makePointer/makeInterface 分别运行 gcflags=-m，记录哪些变量逃逸并解释原因。", "hint": "地址被返回或存入接口的会逃逸。", "answer": "makePointer 的 p 逃逸（&p 返回）；makeInterface 的 p 逃逸（装箱进 any）；makeValue 的 p 可能不逃逸。"}],
        explain="Go 编译器做逃逸分析，决定变量分配在栈还是堆。若变量地址逃出函数（被返回、存入接口、被长期闭包捕获），就分配到堆。用 go build -gcflags=-m 可查看报告。示例给出三种典型写法：按值返回小结构体（常栈分配）、返回局部变量指针（逃逸到堆）、存入 any 接口（通常逃逸）。理解这些差异有助于在性能敏感处减少堆分配、降低 GC 压力。module-project 工程例子（go.mod + main.go），用 go run 运行并可用 -gcflags=-m 观察；desktop only。")
    add("T113", title="剖析：pprof CPU 与内存", level="advanced", kind="module-project", runtime="desktop",
        files=["go.mod", "main.go"], codeFile="main.go", vkind="stdout-exact",
        expected="hot(1000) = 2997\nprofile with: go test -bench . -cpuprofile=cpu.out .\nthen: go tool pprof cpu.out", run="go run .",
        concepts=["pprof", "CPU profile", "内存 profile", "热点"],
        summary="介绍用 go test -cpuprofile 采集剖析、go tool pprof 分析热点的流程。",
        objective="能采集 CPU profile 并用 pprof 定位热点函数。",
        prereq=["T108 基准测试与 b.RunParallel", "T112 内存分配与逃逸分析"],
        pitfalls=["对过短的负载采集 profile：样本不足，热点不准。", "只看 CPU 忽略内存：分配热点同样影响吞吐，应结合 -memprofile。"],
        exercises=[{"prompt": "编写一个基准并采集 cpu.out，用 pprof top 找出占比最高的函数。", "hint": "go tool pprof -top cpu.out。", "answer": "go test -bench . -cpuprofile=cpu.out .; go tool pprof -top cpu.out。"}],
        explain="pprof 是 Go 的剖析工具。最简单的方式是在测试里采集：go test -bench . -cpuprofile=cpu.out 生成 CPU 剖面，go tool pprof cpu.out 进入交互式分析（top 看热点、list 看源码行）。示例提供一个 CPU 热点函数 hot 并打印确定结果，同时在注释中给出采集命令。剖析是性能优化的起点：先测量热点，再针对性优化，避免凭直觉改代码。module-project，go test 采集 + go run 演示；desktop only（移动端无 pprof 工具链）。")
    add("T114", title="性能优化范式：预分配、批处理、零拷贝", level="advanced", kind="test-package", runtime="desktop",
        files=["go.mod", "patterns_test.go"], codeFile="patterns_test.go", vkind="bench-exists", expected="", run="go test -bench . -run '^$' ./...",
        concepts=["预分配", "strings.Builder", "分配", "benchmark"],
        summary="用预分配切片与 strings.Builder 降低分配，用功能等价断言 + 基准参考验证。",
        objective="能用 make([]T,0,n) 预分配、用 strings.Builder 拼接来减少分配次数。",
        prereq=["T036 字符串构造：strings.Builder 与字节缓冲", "T108 基准测试与 b.RunParallel"],
        pitfalls=["预分配过大的容量：浪费内存；应按已知规模估计。", "把“分配次数必须为 0”当通用断言：某些场景无法避免分配，应看基准而非硬阈值。"],
        exercises=[{"prompt": "为 appendPrealloc 与 appendNoPrealloc 增加基准，对比 allocs/op。", "hint": "b.ReportAllocs()。", "answer": "BenchmarkAppendNoPrealloc 与 BenchmarkAppendPrealloc 各 b.ReportAllocs() 后循环。"}],
        explain="常见优化范式：一是预分配，make([]int, 0, n) 避免 append 反复扩容；二是用 strings.Builder 拼接字符串，避免每次 + 都产生新字符串；三是复用缓冲（见 T080 Pool）。示例对比预分配与不预分配、Builder 与 + 拼接，功能上结果等价（用确定性等价断言验证），性能差异用基准展示——但基准数值不作通过条件。这类优化在热路径上能显著减少分配与 GC。test-package，bench 需官方 SDK，desktop only。")
    add("T115", title="静态检查与工程规范：vet 与 gofmt 基线", level="beginner", kind="single-file", runtime="desktop",
        files=["main.go"], codeFile="main.go", vkind="stdout-exact",
        expected="total: 6\nhello, gopher (3 items)\nrun: `gofmt -l .` and `go vet ./...`", run="go run main.go",
        concepts=["gofmt", "go vet", "规范", "静态检查"],
        summary="用 gofmt 统一格式、go vet 检查可疑构造，作为标准库自带的静态检查基线。",
        objective="能用 gofmt -l/-d 与 go vet 保持代码风格与正确性。",
        prereq=["T001 Go 语言与工具链概览"],
        pitfalls=["依赖手工对齐而非 gofmt：团队风格不一致。", "以为 vet 能发现所有 bug：vet 只查可疑构造，不替代测试。"],
        exercises=[{"prompt": "对 samples 目录运行 gofmt -l 与 go vet ./...，修正所有输出。", "hint": "gofmt -w 自动修复格式。", "answer": "gofmt -l 应无输出；go vet 应无告警。"}],
        explain="gofmt 是 Go 的官方格式化器：-l 列出不合规文件，-d 显示差异，-w 直接改写。go vet 检查可疑构造，如 Printf 动词与参数不匹配、锁值拷贝、无用标签等。二者随工具链提供，是无需第三方依赖的静态检查基线。示例本身格式规范、Printf 参数匹配，可作为“干净”的检查对象，并打印运行命令。single-file 示例可被 CodeSnippet 导入；静态检查需官方 SDK，移动端不提供，desktop only。")
    add("T116", title="日志与可观测性基线：log/slog", level="intermediate", kind="single-file", runtime="desktop",
        files=["main.go"], codeFile="main.go", vkind="stdout-exact",
        expected='level=INFO msg="server starting" addr=127.0.0.1:8080 pid=1\nlevel=WARN msg="slow query" component=db ms=120\n{"level":"ERROR","msg":"failed to connect","host":"db1"}\nlevel=INFO msg="shutdown complete"', run="go run main.go",
        concepts=["slog", "结构化日志", "级别", "go1.21"],
        summary="用 log/slog 输出结构化日志（Text/JSON），设置级别并用 ReplaceAttr 保证输出确定。",
        objective="能用 slog 记录结构化字段、设置级别，并理解 Text/JSON handler 的差异。",
        prereq=["T008 格式化输出与 fmt 谓词"],
        pitfalls=["log/slog 需要 Go 1.21+：低版本不可用。", "默认 Text handler 带时间戳：会破坏确定性；示例用 ReplaceAttr 去掉 time 字段。", "平台限制：本主题在移动端 Yaegi 解释器下 log/slog 输出为空，仅桌面官方 Go 可运行（保持 desktop-only）。"],
        exercises=[{"prompt": "把级别提到 Warn，验证 Info 日志被过滤。", "hint": "HandlerOptions{Level: slog.LevelWarn}。", "answer": "级别设为 Warn 后 Info 不输出，只有 Warn/Error 出现。"}],
        explain="log/slog（Go 1.21+）提供结构化日志：字段以 key=value 形式输出，可被机器检索。Text handler 输出人类可读行，JSON handler 输出单行 JSON。可设级别（Info/Warn/Error）过滤低级别日志。为使示例输出确定，用 ReplaceAttr 去掉默认的 time 属性——日志时间依赖运行时刻，不能作为固定输出。示例演示 Info/Warn 结构化字段、Debug 被过滤、以及 JSON handler 的 Error 输出。移动端 slog 支持未实测，标 Yaegi*（待实测），默认 desktop。")
    add("T117", title="配置、标志与环境变量", level="intermediate", kind="single-file", runtime="desktop",
        files=["main.go"], codeFile="main.go", vkind="stdout-exact",
        expected="addr=192.168.1.5 level=warn port=9000\naddr=10.0.0.1 level=warn port=8080\naddr=127.0.0.1 level=info port=8080", run="go run main.go",
        concepts=["flag", "环境变量", "配置优先级", "默认值"],
        summary="用 flag 与环境变量分层注入配置，命令行优先于环境变量优先于默认值。",
        objective="能用 flag 解析命令行参数、按优先级合并环境变量与默认值。",
        prereq=["T067 包级 API 设计与向后兼容"],
        pitfalls=["直接 os.Getenv 而不设默认值：缺失时得到空字符串，产生隐蔽 bug。", "在 flag.Parse 之后才注册 flag：不会被解析，需在 Parse 前注册。"],
        exercises=[{"prompt": "增加一个 --verbose 布尔标志，并让环境变量 APP_VERBOSE=1 也能开启。", "hint": "用 fs.Bool 与 getenv 合并。", "answer": "level := fs.Bool(\"verbose\", getenv(\"APP_VERBOSE\")==\"1\", ...)。"}],
        explain="配置常来自三处：默认值、环境变量、命令行标志。惯例优先级是命令行 > 环境变量 > 默认值。示例把 getenv 作为参数注入（而非直接读环境），从而在测试与演示中得到确定结果：带标志时标志覆盖环境变量，不带标志时环境变量生效，都没有时用默认值。用 flag.NewFlagSet 便于隔离与测试。这种分层注入让配置既灵活又可测，是 CLI/服务配置的常见基线。")
